    {
      "name": "PiLp.enorm_apply_le",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ {p : ENNReal} {ι : Type u_2} {β : ι → Type u_4} [hp : Fact (1 ≤ p)] [inst : Fintype ι]\n  [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)] (x : PiLp p β) (i : ι), ‖x.ofLp i‖ₑ ≤ ‖x‖ₑ"
    },
    {
      "name": "PiLp.nnnorm_toLp_single",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ (p : ENNReal) {ι : Type u_2} (β : ι → Type u_4) [hp : Fact (1 ≤ p)] [inst : Fintype ι]\n  [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)] [inst_2 : DecidableEq ι] (i : ι) (b : β i),\n  ‖WithLp.toLp p (Pi.single i b)‖₊ = ‖b‖₊"
    },
    {
      "name": "PiLp.norm_apply_le",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ {p : ENNReal} {ι : Type u_2} {β : ι → Type u_4} [hp : Fact (1 ≤ p)] [inst : Fintype ι]\n  [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)] (x : PiLp p β) (i : ι), ‖x.ofLp i‖ ≤ ‖x‖"
    },
    {
      "name": "lp.norm_apply_le_norm",
      "module_name": "Mathlib.Analysis.Normed.Lp.lpSpace",
      "kind": "theorem",
      "type": "∀ {α : Type u_3} {E : α → Type u_4} {p : ENNReal} [inst : (i : α) → NormedAddCommGroup (E i)],\n  p ≠ 0 → ∀ (f : ↥(lp E p)) (i : α), ‖↑f i‖ ≤ ‖f‖"
    },
    {
      "name": "lp.norm_le_of_tsum_le",
      "module_name": "Mathlib.Analysis.Normed.Lp.lpSpace",
      "kind": "theorem",
      "type": "∀ {α : Type u_3} {E : α → Type u_4} {p : ENNReal} [inst : (i : α) → NormedAddCommGroup (E i)],\n  0 < p.toReal → ∀ {C : ℝ}, 0 ≤ C → ∀ {f : ↥(lp E p)}, ∑' (i : α), ‖↑f i‖ ^ p.toReal ≤ C ^ p.toReal → ‖f‖ ≤ C"
    }
  ]
}
